import java.util.Scanner;

public class RobotNavigation {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        while (sc.hasNextInt()) {
            int m = sc.nextInt();
            int n = sc.nextInt();
            if (m == 0 && n == 0) break;

            int x = 1, y = 1;
            sc.nextLine(); // consume the rest of the line

            while (sc.hasNextLine()) {
                String command = sc.nextLine().trim();
                if (command.equals("STOP")) {
                    break;
                }

                switch (command) {
                    case "FORWARD":
                        if (y < n) y++;
                        break;
                    case "BACKWARD":
                        if (y > 1) y--;
                        break;
                    case "LEFT":
                        if (x > 1) x--;
                        break;
                    case "RIGHT":
                        if (x < m) x++;
                        break;
                }
            }

            System.out.println(x + " " + y);
        }

        sc.close();
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNextInt()) {
            int rows = sc.nextInt();
            int cols = sc.nextInt();

            // Robot starts at center
            int startRow = (rows + 1) / 2;
            int startCol = (cols + 1) / 2;
            int r = startRow, c = startCol;

            // Direction: 0=North, 1=East, 2=South, 3=West
            int dir = 0;
            int[] dr = {-1, 0, 1, 0}; // North=up means row decreases
            int[] dc = {0, 1, 0, -1};

            boolean stopped = false;
            while (!stopped && sc.hasNext()) {
                String cmd = sc.next();
                switch (cmd) {
                    case "FORWARD":
                        r = Math.max(1, Math.min(rows, r + dr[dir]));
                        c = Math.max(1, Math.min(cols, c + dc[dir]));
                        break;
                    case "BACKWARD":
                        r = Math.max(1, Math.min(rows, r - dr[dir]));
                        c = Math.max(1, Math.min(cols, c - dc[dir]));
                        break;
                    case "LEFT":
                        dir = (dir + 3) % 4;
                        break;
                    case "RIGHT":
                        dir = (dir + 1) % 4;
                        break;
                    case "STOP":
                        stopped = true;
                        break;
                }
            }

            // Output relative to start (center = (1,1))
            int outR = r - startRow + 1;
            int outC = c - startCol + 1;
            System.out.println(outR + " " + outC);
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line;
        StringBuilder out = new StringBuilder();

        while ((line = br.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) continue;

            StringTokenizer st = new StringTokenizer(line);
            if (st.countTokens() < 2) continue;

            int width = Integer.parseInt(st.nextToken());
            int height = Integer.parseInt(st.nextToken());

            // Common termination condition for this classic robot problem
            if (width == 0 && height == 0) break;

            int x = 1, y = 1;

            while ((line = br.readLine()) != null) {
                line = line.trim();
                if (line.isEmpty()) continue;

                if (line.equals("STOP")) break;

                st = new StringTokenizer(line);
                String cmd = st.nextToken();
                int k = Integer.parseInt(st.nextToken());

                if (cmd.equals("FORWARD")) {
                    y = Math.min(height, y + k);
                } else if (cmd.equals("BACKWARD")) {
                    y = Math.max(1, y - k);
                } else if (cmd.equals("RIGHT")) {
                    x = Math.min(width, x + k);
                } else if (cmd.equals("LEFT")) {
                    x = Math.max(1, x - k);
                }
            }

            out.append(x).append(' ').append(y).append('\n');
        }

        System.out.print(out.toString());
    }
}

import sys

def solve():
    data = [line.strip() for line in sys.stdin if line.strip()]
    if not data:
        return

    out = []
    i = 0
    while i < len(data):
        # Read field size
        w, h = map(int, data[i].split())
        i += 1

        x, y = 1, 1

        # Process commands until STOP
        while i < len(data):
            parts = data[i].split()
            i += 1

            cmd = parts[0]
            if cmd == "STOP":
                out.append(f"{x} {y}")
                break

            n = int(parts[1])

            if cmd == "FORWARD":
                y = min(h, y + n)
            elif cmd == "BACKWARD":
                y = max(1, y - n)
            elif cmd == "RIGHT":
                x = min(w, x + n)
            elif cmd == "LEFT":
                x = max(1, x - n)

    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    solve()
